def transform(g):
    h,w=len(g),len(g[0])
    out=[r[:] for r in g]
    for c in range(w):
        if g[h-1][c]!=5: continue
        below=None
        for r in range(h-1,-1,-1):
            if g[r][c]!=0: below=g[r][c]
            elif below is not None: out[r][c]=below
    return out
